head.b:skin:
:root {
  --bg-color: #f0f2f5;
  --text-color: #1e293b;
  --primary-color: #2563eb;
  --accent-color: #f97316;
  --card-bg: #ffffff;
  --header-bg: #ffffff;
  --nav-text: #334155;
  --border-color: #e2e8f0;
  --shadow: 0 4px 6px -1px rgb(0 0 0 / 0.1);
}

[data-theme='dark'] {
  --bg-color: #0f172a;
  --text-color: #f8fafc;
  --primary-color: #38bdf8;
  --accent-color: #fb923c;
  --card-bg: #1e293b;
  --header-bg: #0f172a;
  --nav-text: #cbd5e1;
  --border-color: #334155;
  --shadow: 0 4px 6px -1px rgb(0 0 0 / 0.3);
}

body {
  font-family: 'Roboto', sans-serif;
  background-color: var(--bg-color);
  color: var(--text-color);
  margin: 0;
  transition: background-color 0.3s, color 0.3s;
}

h1, h2, h3, .logo {
  font-family: 'Orbitron', sans-serif;
}

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 20px;
}

/* Header & Nav */
header {
  background: var(--header-bg);
  border-bottom: 2px solid var(--primary-color);
  padding: 1rem 0;
  position: sticky;
  top: 0;
  z-index: 100;
  box-shadow: var(--shadow);
}

.header-inner {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.logo a {
  text-decoration: none;
  color: var(--primary-color);
  font-size: 1.5rem;
  font-weight: 700;
  display: flex;
  align-items: center;
  gap: 10px;
}

nav ul {
  display: flex;
  list-style: none;
  gap: 20px;
  margin: 0;
  padding: 0;
}

nav a {
  text-decoration: none;
  color: var(--nav-text);
  font-weight: 500;
  text-transform: uppercase;
  font-size: 0.9rem;
  letter-spacing: 1px;
  transition: color 0.3s;
}

nav a:hover {
  color: var(--primary-color);
}

/* Theme Toggle */
#theme-toggle {
  background: none;
  border: 2px solid var(--border-color);
  color: var(--text-color);
  padding: 8px;
  border-radius: 50%;
  cursor: pointer;
  width: 40px;
  height: 40px;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: 0.3s;
}

#theme-toggle:hover {
  border-color: var(--primary-color);
  color: var(--primary-color);
}

/* Hero */
.hero {
  background: linear-gradient(rgba(0,0,0,0.7), rgba(0,0,0,0.7)), url('https://images.unsplash.com/photo-1581092160562-40aa08e78837?auto=format&fit=crop&q=80&w=1200') center/cover;
  color: white;
  padding: 100px 0;
  text-align: center;
  margin-bottom: 40px;
  border-bottom: 5px solid var(--accent-color);
}

.hero h1 {
  font-size: 3.5rem;
  margin-bottom: 20px;
  text-shadow: 0 0 15px var(--primary-color);
}

/* Grid Layout */
.main-grid {
  display: grid;
  grid-template-columns: 1fr 320px;
  gap: 30px;
}

@media (max-width: 991px) {
  .main-grid { grid-template-columns: 1fr; }
}

/* Article Cards */
.post-card {
  background: var(--card-bg);
  border-radius: 8px;
  overflow: hidden;
  margin-bottom: 30px;
  border: 1px solid var(--border-color);
  transition: transform 0.3s, box-shadow 0.3s;
}

.post-card:hover {
  transform: translateY(-5px);
  box-shadow: 0 10px 20px rgba(0,0,0,0.1);
}

.post-image {
  height: 250px;
  background-color: #334155;
  background-size: cover;
  background-position: center;
}

.post-info {
  padding: 25px;
}

.post-tag {
  background: var(--primary-color);
  color: white;
  padding: 4px 12px;
  border-radius: 20px;
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
}

.post-title {
  margin: 15px 0;
  font-size: 1.5rem;
}

.post-title a {
  color: var(--text-color);
  text-decoration: none;
}

/* Widgets */
.widget {
  background: var(--card-bg);
  padding: 20px;
  border-radius: 8px;
  margin-bottom: 30px;
  border: 1px solid var(--border-color);
}

.widget h2 {
  font-size: 1.1rem;
  color: var(--accent-color);
  margin-bottom: 20px;
  border-bottom: 1px solid var(--border-color);
  padding-bottom: 10px;
  text-transform: uppercase;
}

/* Footer */
footer {
  background: #020617;
  color: #94a3b8;
  padding: 60px 0 20px;
  margin-top: 60px;
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: 40px;
  margin-bottom: 40px;
}

.footer-logo {
  color: white;
  font-family: 'Orbitron', sans-serif;
  font-size: 1.5rem;
  margin-bottom: 20px;
}

.social-links {
  display: flex;
  gap: 15px;
}

.social-links a {
  color: #94a3b8;
  font-size: 1.2rem;
  transition: 0.3s;
}

.social-links a:hover {
  color: var(--primary-color);
}

.btn {
  display: inline-block;
  padding: 10px 25px;
  background: var(--primary-color);
  color: white;
  text-decoration: none;
  border-radius: 4px;
  font-weight: 600;
  transition: 0.3s;
}

.btn:hover {
  background: var(--accent-color);
}

body.script:
// Year
document.getElementById('year').textContent = new Date().getFullYear();

// Theme Toggle Logic
const themeToggle = document.getElementById('theme-toggle');
const body = document.body;
const icon = themeToggle.querySelector('i');

// Check for saved theme
const savedTheme = localStorage.getItem('robo-theme') || 'light';
body.setAttribute('data-theme', savedTheme);
updateIcon(savedTheme);

themeToggle.addEventListener('click', () => {
  const currentTheme = body.getAttribute('data-theme');
  const newTheme = currentTheme === 'light' ? 'dark' : 'light';

  body.setAttribute('data-theme', newTheme);
  localStorage.setItem('robo-theme', newTheme);
  updateIcon(newTheme);
});

function updateIcon(theme) {
  if (theme === 'dark') {
    icon.classList.replace('fa-moon', 'fa-sun');
  } else {
    icon.classList.replace('fa-sun', 'fa-moon');
  }
}
